"use strict";module.exports=function(defaultFuncs,api,ctx){return function getEmojiUrl(character,size,pixelRatio){if(!character)throw new Error("character is required");size=size||32;pixelRatio=pixelRatio||"1.0";const codePoint=character.codePointAt(0);if(codePoint===undefined)throw new Error("Invalid character — could not determine code point.");const ending=`${pixelRatio}/${size}/${codePoint.toString(16)}.png`;let hash=317426846;for(let i=0;i<ending.length;i++){hash=(hash<<5)-hash+ending.charCodeAt(i);hash=hash|0}const shard=(hash&255).toString(16).padStart(2,"0");return`https://static.xx.fbcdn.net/images/emoji.php/v8/z${shard}/${ending}`}};
